typedef unsigned int u_int;

#define DEBUG_ENABLE(x) 0
#define NGL_CPU_CLOCKS_PER_MS 294912.0f
#define D1_CHCR ((volatile u_int*)0x10009000)
#define D2_CHCR ((volatile u_int*)0x1000a000)
#define VIF1_FBRST ((volatile u_int*)0x10003c10)
#define GIF_CTRL ((volatile u_int*)0x10003000)

extern volatile bool nglDMAFinished;
extern bool nglStopOnDmaTimeout;
extern bool nglCompleteFrame;
extern int _nglVif1IntEntryIdx;
extern int _nglNVif1IntEntries;
extern "C" int scePcStart(int, int, int);
void nglWarning(const char*, ...);

inline long volatile nglGetCPUCycle()
{
  register unsigned long result;
  __asm__ volatile ("mfc0 %0,$9" : "=r" (result));
  return result;
}

void nglVif1SafeWait()
{
  // If the DMA doesn't complete in 100ms then cancel it.
  register u_int Start = nglGetCPUCycle();

  while ( !nglDMAFinished )
  {
    u_int Time = nglGetCPUCycle();
    if ( !DEBUG_ENABLE( VUDebugBreak ) && Time - Start >= NGL_CPU_CLOCKS_PER_MS * 100.0f )
    {
      // all these pretty variables are for deciding if we should wait to restart or not
      nglCompleteFrame = !nglStopOnDmaTimeout;
      while (!nglCompleteFrame)
			{
#if !NGL_USE_SN_TUNER
        scePcStart( 0, 0, 0 );
#endif
			}
      // print message
      nglWarning( "NGL: Vif1 DMA Timeout, resetting VIF1/GIF.\n" );
#ifndef NGL_FINAL
//      nglDMATimeoutCounter = 120;
#endif
      // stops dma on channel one ...
      *D1_CHCR = 1 | (1<<2) | (0<<4) | (0<<6) | (0<<7) | (0<<8);
      *D2_CHCR = 1 | (1<<2) | (0<<4) | (0<<6) | (0<<7) | (0<<8);
      // resets the vif1
      *VIF1_FBRST = 1 | (1<<3);
      // resets the gif
      *GIF_CTRL = 1;
      // jump out of the loop
      break;
    }
  }
  if ( _nglVif1IntEntryIdx != _nglNVif1IntEntries )
    nglWarning( "NGL: Not enough interrupts received (%d/%d).\n", _nglVif1IntEntryIdx, _nglNVif1IntEntries );
}
